// NEW decorative/background patch candidate only. Original map PNG is never edited.
export const OPENING_PATCH=Object.freeze({revision:'PROLOGUE_FOREST_OPENINGS_IMAGEGEN_CLIPPED_OVERLAY_R5',referenceCrop:Object.freeze([200,40,1000,380]),rois:Object.freeze([Object.freeze([495,135,625,250]),Object.freeze([785,135,920,250])]),rootSelected:false});
export function drawOpeningOverlay(ctx,patch,{offsetX=0,offsetY=0,scale=1}={}){if(!Number.isFinite(scale)||scale<=0)throw Error('PATCH_SCALE');ctx.save();try{ctx.beginPath();for(const[x0,y0,x1,y1]of OPENING_PATCH.rois)ctx.rect((x0-offsetX)*scale,(y0-offsetY)*scale,(x1-x0)*scale,(y1-y0)*scale);ctx.clip();ctx.imageSmoothingEnabled=true;const[x,y,w,h]=OPENING_PATCH.referenceCrop;ctx.drawImage(patch,(x-offsetX)*scale,(y-offsetY)*scale,w*scale,h*scale);}finally{ctx.restore()}}
